'use strict';
// Listing-only staged sorting; Status filters keep their existing behavior.
const listSortOptions=[['renewal','Next event'],['price-asc','Price: low to high'],['price-desc','Price: high to low'],['name','Name A–Z'],['subscriptions','Most subscriptions']];
function listSortDescription(value){return value==='subscriptions'?'Platforms with more matching subscriptions appear first.':value.startsWith('price-')?'Price sorting uses the amounts shown on cards. Different currencies stay separate.':value==='name'?'Subscriptions are ordered by platform name.':'Next renewals and trial endings appear first. Undated plans stay last.';}
function listDisplayedPrice(record){if(record.price==null||String(record.price).trim()==='')return null;const amount=Number(record.price);return Number.isFinite(amount)&&amount>=0?amount:null;}
function listPlatformKey(record){if(record.platformId)return 'platform:'+record.platformId;const name=String(record.name||'').trim().toLowerCase(),catalog=typeof manualServices==='undefined'?[]:manualServices,match=catalog.find(entry=>[entry[0],...(entry[3]||[])].some(alias=>String(alias).trim().toLowerCase()===name));return match?.[2]?'platform:'+match[2]:'record:'+record.id;}
function listSortItems(items,view=listView){const tie=(a,b)=>a.name.localeCompare(b.name)||String(a.id).localeCompare(String(b.id)),next=(a,b)=>(a.renewal||'9999').localeCompare(b.renewal||'9999')||tie(a,b),groups=new Map();if(view.sort==='subscriptions')for(const record of items){const key=listPlatformKey(record),group=groups.get(key)||{count:0,name:record.name};group.count++;if(record.name.localeCompare(group.name)<0)group.name=record.name;groups.set(key,group);}return [...items].sort((a,b)=>{if(view.sort==='subscriptions'){const ak=listPlatformKey(a),bk=listPlatformKey(b),ag=groups.get(ak),bg=groups.get(bk);return ak===bk?next(a,b):bg.count-ag.count||ag.name.localeCompare(bg.name)||ak.localeCompare(bk);}if(view.sort==='name')return tie(a,b);if(view.sort.startsWith('price-')){const currency=(a.currency||'USD').localeCompare(b.currency||'USD');if(currency)return currency;const av=listDisplayedPrice(a),bv=listDisplayedPrice(b);if(av===null||bv===null)return (av===null)-(bv===null)||tie(a,b);return (av-bv)*(view.sort==='price-asc'?1:-1)||tie(a,b);}return next(a,b);});}
function listSortTrigger(){const label=listSortOptions.find(([value])=>value===listView.sort)?.[1]||'Next event';return `<button class="list-filter-trigger list-sort-trigger" data-open-list-sort aria-haspopup="dialog" aria-expanded="false" aria-label="Sort by: ${escape(label)}" title="Sort by: ${escape(label)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14m-3-3 3 3 3-3M15 6h5m-5 6h4m-4 6h3"/></svg><span class="list-sort-label"><small>Sort by</small><span>${escape(label)}</span></span></button>`;}

function closeListSort(phone){closeSelectMenu(false);const overlay=phone.querySelector('.list-sort-overlay');if(!overlay)return;overlay.remove();phone.querySelectorAll('[data-list-sort-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-list-sort-inert');});const trigger=phone.querySelector('[data-open-list-sort]');trigger?.setAttribute('aria-expanded','false');trigger?.removeAttribute('aria-controls');trigger?.focus({preventScroll:true});}
function openListSort(trigger){closeSelectMenu(false);const phone=trigger.closest('.phone');closeListFilter(phone);const overlay=document.createElement('div');overlay.className='list-sort-overlay';overlay.innerHTML=`<div class="list-filter-shade" data-close-list-sort></div><form class="status-filter-dialog sort-price-dialog" role="dialog" aria-modal="true" aria-labelledby="${phone.id}-sort-title" id="${phone.id}-sort-dialog" style="max-height:${phone.clientHeight-64}px"><header><div><h3 id="${phone.id}-sort-title">Sort by</h3><p>Choose how your subscriptions are ordered.</p></div><button type="button" data-close-list-sort aria-label="Close sorting">×</button></header><div class="sort-price-body"><fieldset><legend class="sort-options-legend">Subscription order</legend>${listSortOptions.map(([value,label])=>`<label class="status-filter-option"><input type="radio" name="order" value="${value}" ${listView.sort===value?'checked':''}><span>${label}</span></label>`).join('')}</fieldset><p class="note" data-sort-note>${listSortDescription(listView.sort)}</p></div><footer><button type="button" class="filter-clear-all" data-reset-list-sort>Reset</button><button class="filter-done" type="submit">Apply</button></footer></form>`;for(const el of phone.children)if(!el.inert){el.inert=true;el.dataset.listSortInert='true';}phone.append(overlay);trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls',phone.id+'-sort-dialog');overlay.querySelector('[data-close-list-sort]').focus();}
document.addEventListener('click',event=>{const open=event.target.closest('[data-open-list-sort]'),close=event.target.closest('[data-close-list-sort]'),reset=event.target.closest('[data-reset-list-sort]');if(open)openListSort(open);else if(close)closeListSort(close.closest('.phone'));else if(reset){const form=reset.closest('form');form.elements.order.value='renewal';form.querySelector('[data-sort-note]').textContent=listSortDescription('renewal');}});
document.addEventListener('submit',event=>{const form=event.target.closest('.sort-price-dialog');if(!form)return;event.preventDefault();listView.sort=form.elements.order.value;const phone=form.closest('.phone');closeListSort(phone);refreshListResults();phone.querySelector('[data-open-list-sort]').outerHTML=listSortTrigger();phone.querySelector('[data-open-list-sort]').focus({preventScroll:true});});
document.addEventListener('keydown',event=>{if(event.defaultPrevented)return;const overlay=document.querySelector('.list-sort-overlay');if(!overlay)return;if(event.key==='Escape'){event.preventDefault();closeListSort(overlay.closest('.phone'));}else if(event.key==='Tab'){const controls=[...overlay.querySelectorAll('button:not([disabled]),input')],first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

document.addEventListener('change',event=>{if(event.target.matches('.sort-price-dialog input[name=order]'))event.target.form.querySelector('[data-sort-note]').textContent=listSortDescription(event.target.value);});
